   101        while (*ref++ == x) ip++;
   102        return ip;
   103      }
   104      else {
   105        ip += sizeof(__m128i);
   106        ref += sizeof(__m128i);
   107      }
   108    }
   109    /* Look into the remainder */
   110    while ((ip < ip_bound) && (*ref++ == x)) ip++;
