   246  #define LITERAL(ip, op, op_limit, anchor, copy) {       \
   247    if (BLOSCLZ_UNLIKELY(op + 2 > op_limit))              \
   248      goto out;                                           \
   249    *op++ = *anchor++;                                    \
   250    ip = anchor;                                          \
   251    copy++;                                               \
   252    if (BLOSCLZ_UNLIKELY(copy == MAX_COPY)) {             \
   253      copy = 0;                                           \
   254      *op++ = MAX_COPY-1;                                 \
   255    }                                                     \
   256  }
   257
   258  #define LITERAL2(ip, anchor, copy) {                    \
   259    oc++; anchor++;                                       \
   260    ip = anchor;                                          \
   261    copy++;                                               \
   262    if (BLOSCLZ_UNLIKELY(copy == MAX_COPY)) {             \
   263      copy = 0;                                           \
   264      oc++;                                               \
   265    }                                                     \
   266  }
