   317  // Get a guess for the compressed size of a buffer
   318  static double get_cratio(uint8_t* ibase, int maxlen, int minlen, int ipshift) {
   319    uint8_t* ip = ibase;
   320    int32_t oc = 0;
   321    const uint16_t hashlen = (1U << (uint8_t)HASH_LOG2);
   322    uint16_t htab[1U << (uint8_t)HASH_LOG2];
   323    uint32_t hval;
   324    uint32_t seq;
   325    uint8_t copy;
   326    // Make a tradeoff between testing too much and too little
   327    uint16_t limit = (maxlen > hashlen) ? hashlen : maxlen;
   328    uint8_t* ip_bound = ibase + limit - 1;
   329    uint8_t* ip_limit = ibase + limit - 12;
   330
   331    // Initialize the hash table to distances of 0
   332    memset(htab, 0, hashlen * sizeof(uint16_t));
   333
   334    /* we start with literal copy */
   335    copy = 4;
   336    oc += 5;
   337
   338    /* main loop */
   339    while (BLOSCLZ_LIKELY(ip < ip_limit)) {
   340      const uint8_t* ref;
   341      unsigned distance;
   342      uint8_t* anchor = ip;    /* comparison starting-point */
   343
   344      /* find potential match */
   345      seq = BLOSCLZ_READU32(ip);
   346      HASH_FUNCTION(hval, seq, HASH_LOG2)
   347      ref = ibase + htab[hval];
   348
   349      /* calculate distance to the match */
   350      distance = (unsigned int)(anchor - ref);
   351
   352      /* update hash table */
   353      htab[hval] = (uint16_t) (anchor - ibase);
   354
   355      if (distance == 0 || (distance >= MAX_FARDISTANCE)) {
   356        LITERAL2(ip, anchor, copy)
   357        continue;
   358      }
   359
   360      /* is this a match? check the first 4 bytes */
   540      else
   541        /* back, to overwrite the copy count */
   542        op--;
   543      /* reset literal counter */
   544      copy = 0;
   545
   546      /* encode the match */
   547      if (distance < MAX_DISTANCE) {
   548        if (len < 7) {
   549          MATCH_SHORT(op, op_limit, len, distance)
   550        } else {
   551          MATCH_LONG(op, op_limit, len, distance)
   552        }
   553      } else {
   554        /* far away, but not yet in the another galaxy... */
   555        distance -= MAX_DISTANCE;
   556        if (len < 7) {
   557          MATCH_SHORT_FAR(op, op_limit, len, distance)
   558        } else {
   559          MATCH_LONG_FAR(op, op_limit, len, distance)
   560        }
   561      }
   562
   563      /* update the hash at match boundary */
   564      seq = BLOSCLZ_READU32(ip);
   565      HASH_FUNCTION(hval, seq, hashlog)
   566      htab[hval] = (uint32_t) (ip++ - ibase);
   567      if (clevel == 9) {
   568        // In some situations, including a second hash proves to be useful,
   569        // but not in others.  Activating here in max clevel only.
   570        seq >>= 8U;
   571        HASH_FUNCTION(hval, seq, hashlog)
   572        htab[hval] = (uint32_t) (ip++ - ibase);
   573      }
   574      else {
   575        ip++;
   576      }
   577
   578      if (BLOSCLZ_UNLIKELY(op + 1 > op_limit))
   579        goto out;
   580
   581      /* assuming literal copy */
   582      *op++ = MAX_COPY - 1;
   583    }
   584
   585    /* left-over as literal copy */
   586    while (BLOSCLZ_UNLIKELY(ip <= ip_bound)) {
   587      if (BLOSCLZ_UNLIKELY(op + 2 > op_limit)) goto out;
   588      *op++ = *ip++;
   589      copy++;
   590      if (BLOSCLZ_UNLIKELY(copy == MAX_COPY)) {
   591        copy = 0;
   592        *op++ = MAX_COPY - 1;
   593      }
   594    }
   595
   596    /* if we have copied something, adjust the copy length */
   597    if (copy)
   598      *(op - copy - 1) = (uint8_t)(copy - 1);
   599    else
   600      op--;
   601
   602    /* marker for blosclz */
   603    *(uint8_t*)output |= (1U << 5U);
   604
   605    return (int)(op - (uint8_t*)output);
   606
   607    out:
   608    return 0;
   609  }
